/* eslint-disable react-refresh/only-export-components */
import { EstimateResponse } from '@/@types/services/petition';
import { Card, Col, Descriptions, DescriptionsProps, Image, message, Row, Spin } from 'antd';
import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { useAppSelector } from '@/store';
import { useRouteContext } from '../../../context';
import { getUploadAPI } from '@/services/entrepreneur/VehicleListService';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Pagination } from 'swiper/modules'
// Import Swiper styles
import 'swiper/css';
import 'swiper/css/pagination';

interface Props {
  item: EstimateResponse;
  index: number;
}

interface ImageState {
  front: string;
  back: string;
  side: string;
}

const INIT_IMG_STATE: ImageState = {
  front: '',
  back: '',
  side: ''
}

const ContentDetail: React.FC<Props> = (props) => {
  const { index } = props
  const { dataParser } = useRouteContext()
  const { estimate } = useAppSelector(state => state.entrepreneur.permitList)
  const { vehicle_selection } = useAppSelector(state => state.master)
  const { loading } = useAppSelector(state => state.layout)
  const detail = estimate.detail
  // IMG
  const [towingImage, setTowingImage] = useState<ImageState>(INIT_IMG_STATE)
  const [semiImage, setSemiImage] = useState<ImageState>(INIT_IMG_STATE)
  // const [etcImage, setEtcImage] = useState<ImageState>(INIT_IMG_STATE)
  const [etcImage, setEtcImage] = useState<{ [key: number]: ImageState }>({})

  const selectTowing = vehicle_selection.data.find(item => item.vehicle_detail?.id === dataParser.raw_body.route_form[index]?.towering_vehicle) || null
  const selectSemi = vehicle_selection.data.find(item => item.vehicle_detail?.id === dataParser.raw_body.route_form[index]?.semi_trailer_vehicle) || null
  // const selectETC = vehicle_selection.data.find(item => item.vehicle_detail?.id === dataParser.raw_body.route_form[index]?.etc_vehicle) || null

  const extractUrl = useCallback((url: string) => {
    const path = url.split('/upload')[1];
    return path
  }, []);

  const fetchImage = useCallback(async (stateType: 'towing' | 'semi' | 'etc', imgUrl: string[], etcId?: number) => {
    try {
      const response = await Promise.all(imgUrl.map(item => getUploadAPI(item as string)))
      const result = response.every(item => item.status === 200)
      if (result) {
        if (stateType === 'towing') {
          const imgArr = response.map((item) => {
            const blobFile = new Blob([item.data], { type: item.data.type })
            const url = URL.createObjectURL(blobFile)
            return url
          })
          setTowingImage({
            front: imgArr[0],
            back: imgArr[1],
            side: imgArr[2],
          })
        }
        if (stateType === 'semi') {
          const imgArr = response.map((item) => {
            const blobFile = new Blob([item.data], { type: item.data.type })
            const url = URL.createObjectURL(blobFile)
            return url
          })
          setSemiImage({
            front: imgArr[0],
            back: imgArr[1],
            side: imgArr[2],
          })
        }
        // if (stateType === 'etc') {
        //   const imgArr = response.map((item) => {
        //     const blobFile = new Blob([item.data], { type: item.data.type })
        //     const url = URL.createObjectURL(blobFile)
        //     return url
        //   })
        //   setEtcImage({
        //     front: imgArr[0],
        //     back: imgArr[1],
        //     side: imgArr[2],
        //   })
        // }
        if (stateType === 'etc' && etcId) {
          const imgArr = response.map((item) => {
            const blobFile = new Blob([item.data], { type: item.data.type })
            const url = URL.createObjectURL(blobFile)
            return url
          })
          setEtcImage(prev => ({
            ...prev,
            [etcId]: {
              front: imgArr[0],
              back: imgArr[1],
              side: imgArr[2],
            }
          }))
        }
      }
    } catch (error) {
      if (error instanceof Error) {
        message.error(error.message)
      } else {
        console.error(error)
      }
    }
  }, [])

  useEffect(() => {
    if (selectTowing?.vehicle_pictures.front_rear_url) {
      if (extractUrl(selectTowing?.vehicle_pictures.front_rear_url)) {
        fetchImage('towing', [
          extractUrl(selectTowing?.vehicle_pictures.front_rear_url),
          extractUrl(selectTowing?.vehicle_pictures.back_rear_url),
          extractUrl(selectTowing?.vehicle_pictures.side_rear_url),
        ])
      }
    }
    if (selectSemi?.vehicle_pictures.front_rear_url) {
      if (extractUrl(selectSemi?.vehicle_pictures.front_rear_url)) {
        fetchImage('semi', [
          extractUrl(selectSemi?.vehicle_pictures.front_rear_url),
          extractUrl(selectSemi?.vehicle_pictures.back_rear_url),
          extractUrl(selectSemi?.vehicle_pictures.side_rear_url),
        ])
      }
    }
    // if (selectETC?.vehicle_pictures.front_rear_url) {
    //   if (extractUrl(selectETC?.vehicle_pictures.front_rear_url)) {
    //     fetchImage('etc', [
    //       extractUrl(selectETC?.vehicle_pictures.front_rear_url),
    //       extractUrl(selectETC?.vehicle_pictures.back_rear_url),
    //       extractUrl(selectETC?.vehicle_pictures.side_rear_url),
    //     ])
    //   }
    // }

    // Handle multiple ETC vehicles
    if (dataParser.raw_body.route_form[index]?.etc_vehicle && Array.isArray(dataParser.raw_body.route_form[index]?.etc_vehicle) && dataParser.raw_body.route_form[index]?.etc_vehicle.length > 0) {
      dataParser.raw_body.route_form[index]?.etc_vehicle.forEach((etcId) => {
        const selectedETC = vehicle_selection.data.find(item => item.vehicle_detail.id === etcId)
        if (selectedETC?.vehicle_pictures.front_rear_url) {
          if (extractUrl(selectedETC?.vehicle_pictures.front_rear_url)) {
            fetchImage('etc', [
              extractUrl(selectedETC?.vehicle_pictures.front_rear_url),
              extractUrl(selectedETC?.vehicle_pictures.back_rear_url),
              extractUrl(selectedETC?.vehicle_pictures.side_rear_url),
            ], etcId)
          }
        }
      })
    }
  }, [
    fetchImage,
    extractUrl,
    selectTowing?.vehicle_pictures.front_rear_url,
    selectTowing?.vehicle_pictures.back_rear_url,
    selectTowing?.vehicle_pictures.side_rear_url,
    selectSemi?.vehicle_pictures.front_rear_url,
    selectSemi?.vehicle_pictures.back_rear_url,
    selectSemi?.vehicle_pictures.side_rear_url,
    dataParser.raw_body.route_form,
    index,
    vehicle_selection?.data
  ])

  const mapPlaceholder = useMemo(() => {
    switch (dataParser.raw_body.route_form[index].match_type) {
      case 1:
        return 'รถลากจูง + รถกึ่งพ่วง + เครื่องจักร / สินค้า'
      case 2:
        return 'รถลากจูง + รถกึ่งพ่วง'
      case 3:
        return 'รถกึ่งพ่วง'
      default:
        return '-'
    }
  }, [dataParser.raw_body.route_form, index])

  const renderLicensePlate = useCallback((plateNo: string, plateProvince: string) => {
    const nameArr = [plateNo, plateProvince]
    if (!nameArr.length) return '-'
    return nameArr.join(' ').trim()
  }, [])

  const items: DescriptionsProps['items'] = [
    {
      key: '1',
      label: 'น้ำหนักลงเพลา รถลากจูง (กิโลกรัม)',
      children: <p>{detail?.towing_axis_weight.join(' : ')}</p>,
    },
    {
      key: '2',
      label: 'น้ำหนักลงเพลา กึ่งรถพ่วง (กิโลกรัม)',
      children: <p>{detail?.semi_trailer_axis_weight.join(' : ')}</p>,
    },
    {
      key: '3',
      label: 'ต้นทาง',
      children: <p>{detail?.start_point.join(',')}</p>,
    },
    {
      key: '4',
      label: 'ปลายทาง',
      children: <p>{detail?.end_point.join(',')}</p>,
    },
  ]

  const renderETC = useCallback((value: number[]) => {
    const arr = []
    if (value?.length) {
      for (const etc_id of value) {
        const selectETC = vehicle_selection.data.find(item => item.vehicle_detail.id === etc_id)
        if (selectETC) {
          arr.push(selectETC)
        }
      }
    }
    if (arr.length) {
      return arr.map((item, index) => {
        const images = etcImage[item.vehicle_detail.id] || INIT_IMG_STATE
        return (
          <Col key={index} xs={24} sm={12} md={12} lg={8} xl={8} xxl={8} >
            <Card
              cover={(
                <Spin spinning={loading}>
                  <Swiper
                    modules={[Pagination]}
                    slidesPerView={1}
                    pagination={true}
                  >
                    <SwiperSlide>
                      <figure className='h-44 relative overflow-hidden'>
                        <Image
                          src={images.front}
                          alt={'etc-vehicle'}
                          width={'100%'}
                          height={'100%'}
                          className='object-cover object-center'
                          fallback='data:image/png;base64,'
                        />
                      </figure>
                    </SwiperSlide>
                    <SwiperSlide>
                      <figure className='h-44 relative overflow-hidden'>
                        <Image
                          src={images.back}
                          alt={'etc-vehicle'}
                          width={'100%'}
                          height={'100%'}
                          className='object-cover object-center'
                          fallback='data:image/png;base64,'
                        />
                      </figure>
                    </SwiperSlide>
                    <SwiperSlide>
                      <figure className='h-44 relative overflow-hidden'>
                        <Image
                          src={images.side}
                          alt={'etc-vehicle'}
                          width={'100%'}
                          height={'100%'}
                          className='object-cover object-center'
                          fallback='data:image/png;base64,'
                        />
                      </figure>
                    </SwiperSlide>
                  </Swiper>
                </Spin>
              )}
            >
              <Card.Meta
                title={renderLicensePlate(item.vehicle_detail.plate_no, item.vehicle_detail.plate_province)}
                description={`${item.vehicle_detail.weight || 0} กก.`}
              />
            </Card>
          </Col>
        )
      })
    }
  }, [loading, renderLicensePlate, vehicle_selection.data, etcImage])

  const getTotalEtcWeight = useCallback(() => {
    if (!dataParser.raw_body.route_form[index]?.etc_vehicle || dataParser.raw_body.route_form[index]?.etc_vehicle.length === 0) return 0;

    return dataParser.raw_body.route_form[index]?.etc_vehicle.reduce((total, etcId) => {
      const selectedETC = vehicle_selection.data.find(item => item.vehicle_detail.id === etcId);
      return total + (selectedETC?.vehicle_detail.weight || 0);
    }, 0);
  }, [dataParser.raw_body.route_form, index, vehicle_selection.data]);

  // 7. Calculate max dimensions for all ETC vehicles
  const getMaxEtcDimensions = useCallback(() => {
    if (!dataParser.raw_body.route_form[index]?.etc_vehicle || dataParser.raw_body.route_form[index]?.etc_vehicle.length === 0) return { width: 0, length: 0, height: 0 };

    return dataParser.raw_body.route_form[index]?.etc_vehicle.reduce((max, etcId) => {
      const selectedETC = vehicle_selection.data.find(item => item.vehicle_detail.id === etcId);
      if (selectedETC) {
        return {
          width: Math.max(max.width, Number(selectedETC.vehicle_detail.width || 0)),
          length: Math.max(max.length, Number(selectedETC.vehicle_detail.length || 0)),
          height: Math.max(max.height, Number(selectedETC.vehicle_detail.height || 0))
        };
      }
      return max;
    }, { width: 0, length: 0, height: 0 });
  }, [dataParser.raw_body.route_form, index, vehicle_selection.data]);

  // Use in your summary section:
  const etcWeight = getTotalEtcWeight();
  const etcDimensions = getMaxEtcDimensions();

  return (
    <>
      <h5>{`รายละเอียด รถคู่ที่ ${index + 1} : ${mapPlaceholder}`}</h5>
      {dataParser.raw_body.route_form[index]?.towering_vehicle || dataParser.raw_body.route_form[index]?.semi_trailer_vehicle ?
        <section className='mt-5'>
          <h5>รูปภาพยานพาหนะ</h5>
          <Row gutter={[16, 16]}>
            {detail?.towing_vehicle ?
              <Col xs={24} sm={12} md={12} lg={12} xl={12} xxl={12}>
                <Card
                  cover={(
                    <Spin spinning={loading}>
                      <Swiper
                        modules={[Pagination]}
                        slidesPerView={1}
                        pagination={true}
                      >
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={towingImage.front}
                              alt={'towering-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={towingImage.back}
                              alt={'towering-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={towingImage.side}
                              alt={'towering-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                      </Swiper>
                    </Spin>
                  )}
                >
                  <Card.Meta
                    title="รถลากจูง"
                    description={(
                      <>
                        <p>{detail?.towing_vehicle?.vehicle_weight || 0} กก.</p>
                        <p>{renderLicensePlate(detail?.towing_vehicle?.vehicle_plate, detail?.towing_vehicle?.vehicle_province)}</p>
                      </>
                    )}
                  />
                </Card>
              </Col>
              : null}
            {detail?.semi_trailer_vehicle ?
              <Col xs={24} sm={12} md={12} lg={12} xl={12} xxl={12}>
                <Card
                  cover={(
                    <Spin spinning={loading}>
                      <Swiper
                        modules={[Pagination]}
                        slidesPerView={1}
                        pagination={true}
                      >
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={semiImage.front}
                              alt={'semi-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={semiImage.back}
                              alt={'semi-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                        <SwiperSlide>
                          <figure className='h-44 relative overflow-hidden'>
                            <Image
                              src={semiImage.side}
                              alt={'semi-vehicle'}
                              width={'100%'}
                              height={'100%'}
                              className='object-cover object-center'
                              fallback='data:image/png;base64,'
                            />
                          </figure>
                        </SwiperSlide>
                      </Swiper>
                    </Spin>
                  )}
                >
                  <Card.Meta
                    title="รถกึ่งพ่วง 4 เพลา 8"
                    description={(
                      <>
                        <p>{detail?.semi_trailer_vehicle?.vehicle_weight || 0} กก.</p>
                        <p>{renderLicensePlate(detail?.semi_trailer_vehicle?.vehicle_plate, detail?.semi_trailer_vehicle?.vehicle_province)}</p>
                      </>
                    )}
                  />
                </Card>
              </Col>
              : null}
          </Row>
        </section>
        : null}
      {dataParser.raw_body.route_form[index]?.etc_vehicle?.length ?
        <section className='mt-5'>
          <h5>รูปภาพเครื่องจักร / สินค้า</h5>
          <Row gutter={[16, 16]}>
            {renderETC(dataParser.raw_body.route_form[index]?.etc_vehicle as number[])}
          </Row>
        </section>
        : null}
      <section className='mt-5'>
        <div className='bg-gray-200 rounded-md p-3'>
          <div className='flex items-center flex-wrap gap-3 justify-between'>
            <p><strong>น้ำหนักรถเปล่ารวม:</strong></p>
            <p>{(
              Number(detail?.towing_vehicle?.vehicle_weight || 0) +
              Number(detail?.semi_trailer_vehicle?.vehicle_weight || 0) +
              // Number(detail?.etc_vehicle?.vehicle_weight || 0)
              etcWeight
              || 0)} กก.
            </p>
          </div>
          <div className='flex items-center flex-wrap gap-3 justify-between'>
            <p><strong>น้ำหนักรถเปล่ารวมน้ำหนักเพลา:</strong></p>
            <p>{(
              Number(detail?.towing_vehicle?.vehicle_weight || 0) +
              Number(detail?.semi_trailer_vehicle?.vehicle_weight || 0) +
              etcWeight +
              Number(detail?.towing_axis_weight[0] || 0) +
              Number(detail?.towing_axis_weight[1] || 0) +
              Number(detail?.towing_axis_weight[2] || 0) +
              Number(detail?.towing_axis_weight[3] || 0) +
              Number(detail?.towing_axis_weight[4] || 0) +
              Number(detail?.towing_axis_weight[5] || 0) +
              Number(detail?.towing_axis_weight[6] || 0) +
              Number(detail?.semi_trailer_axis_weight[0] || 0) +
              Number(detail?.semi_trailer_axis_weight[1] || 0) +
              Number(detail?.semi_trailer_axis_weight[2] || 0) +
              Number(detail?.semi_trailer_axis_weight[3] || 0) +
              Number(detail?.semi_trailer_axis_weight[4] || 0) +
              Number(detail?.semi_trailer_axis_weight[5] || 0) +
              Number(detail?.semi_trailer_axis_weight[6] || 0)
            ) || 0}  กก.
            </p>
          </div>
          <div className='flex items-center flex-wrap gap-3 justify-between'>
            <p><strong>มิติรถเปล่า (ม.):</strong></p>
            <p>{`กว้าง ${Math.max(
              Number(selectTowing?.vehicle_detail?.width || 0),
              Number(selectSemi?.vehicle_detail?.width || 0)
            )} X ยาว ${Math.max(
              Number(selectTowing?.vehicle_detail?.length || 0),
              Number(selectSemi?.vehicle_detail?.length || 0)
            )} X สูง ${Math.max(
              Number(selectTowing?.vehicle_detail?.height || 0),
              Number(selectTowing?.vehicle_detail?.height || 0)
            )}`}</p>
          </div>
          <div className='flex items-center flex-wrap gap-3 justify-between'>
            <p><strong>มิติรถเปล่ารวม เครื่องจักร / สินค้า(ม.):</strong></p>
            <p>{`กว้าง ${Math.max(
              Number(selectTowing?.vehicle_detail.width || 0),
              Number(selectSemi?.vehicle_detail.width || 0),
              etcDimensions.width
            )} X ยาว ${Math.max(
              Number(selectTowing?.vehicle_detail.length || 0),
              Number(selectSemi?.vehicle_detail.length || 0),
              etcDimensions.length
            )} X สูง ${Math.max(
              Number(selectTowing?.vehicle_detail.height || 0),
              Number(selectSemi?.vehicle_detail.height || 0),
              etcDimensions.height
            )}`}</p>
          </div>
        </div>
      </section>
      <section className='mt-5'>
        <Descriptions
          // title=""
          items={items}
          column={1}
          layout='vertical'
          size='small'
        />
      </section>
    </>
  )
}

export default React.memo<Props>(ContentDetail)
